using System;
using UnityEngine;
using UnityEngine.UI;
// Fixed UI pool: presentation randomness never consumes the campaign RNG.
public class SceneParticles : MonoBehaviour {
 public static bool Enabled {get{return PlayerPrefs.GetInt("Besieged.Particles",1)!=0;}set{PlayerPrefs.SetInt("Besieged.Particles",value?1:0);PlayerPrefs.Save();}}
 class Mote {public RectTransform rect;public RawImage image;public Vector2 point,velocity;public float age,life,spin,size;public Color colour;}
 Mote[] pool;RectTransform field;System.Random rng=new System.Random(7321);string kind;static Texture2D soft,leaf;
 public static string KindFor(string key){if(key=="assault-battlefield"||key=="ladder-wall"||key=="walls-war")return "embers";if(key=="market-war")return "smoke";if(key=="market-peace"||key=="walls-peace")return "leaves";if(key=="intelligence")return "dust";return null;}
 public static void Attach(GameObject artwork,string key){var kind=KindFor(key);var old=artwork.GetComponent<SceneParticles>();if(kind==null){if(old!=null)old.Configure(null);return;}var effect=old??artwork.AddComponent<SceneParticles>();effect.Configure(kind);}
 float R(float a,float b){return a+(b-a)*(float)rng.NextDouble();}
 public void Configure(string mode){kind=mode;if(pool!=null)return;field=GetComponent<RectTransform>();pool=new Mote[24];for(int i=0;i<pool.Length;i++){var go=new GameObject("Atmosphere mote",typeof(RectTransform),typeof(RawImage));go.transform.SetParent(transform,false);var m=new Mote{rect=go.GetComponent<RectTransform>(),image=go.GetComponent<RawImage>()};m.rect.anchorMin=m.rect.anchorMax=Vector2.zero;m.image.raycastTarget=false;pool[i]=m;Reset(m,true);}}
 void Reset(Mote m,bool spread){m.age=0;m.life=R(3,7);m.size=kind=="smoke"?R(22,42):kind=="leaves"?R(4,8):R(2,4);m.point=new Vector2(R(0,1),spread?R(0,1):kind=="leaves"?1.02f:0);m.velocity=kind=="leaves"?new Vector2(R(-.04f,.015f),R(-.13f,-.07f)):new Vector2(R(-.018f,.028f),R(.04f,.10f));m.spin=R(-80,80);m.colour=kind=="embers"?new Color(1,.40f,.10f,.40f):kind=="leaves"?new Color(.64f,.46f,.20f,.45f):kind=="smoke"?new Color(.37f,.33f,.29f,.13f):new Color(.85f,.72f,.44f,.18f);m.image.texture=Texture(kind=="leaves");m.rect.sizeDelta=new Vector2(m.size,kind=="leaves"?m.size*.45f:m.size);}
 static Texture2D Texture(bool isLeaf){if(isLeaf&&leaf!=null)return leaf;if(!isLeaf&&soft!=null)return soft;var t=new Texture2D(16,16,TextureFormat.RGBA32,false);for(int y=0;y<16;y++)for(int x=0;x<16;x++){float d=isLeaf?Mathf.Abs((x-7.5f)/8)+Mathf.Abs((y-7.5f)/8):Vector2.Distance(new Vector2(x,y),new Vector2(7.5f,7.5f))/8;float a=Mathf.Clamp01(1-d);t.SetPixel(x,y,new Color(1,1,1,isLeaf?Mathf.Clamp01(a*5):a*a));}t.Apply();if(isLeaf)leaf=t;else soft=t;return t;}
 void Update(){if(pool==null)return;bool visible=Enabled&&kind!=null;bool moving=visible&&Application.isFocused&&(CampaignHUD.Instance==null||!CampaignHUD.Instance.HasModal);float dt=Mathf.Min(Time.unscaledDeltaTime,.05f);foreach(var m in pool){m.image.enabled=visible;if(!moving)continue;m.age+=dt;if(m.age>=m.life||m.point.y<-.05f)Reset(m,false);m.point+=m.velocity*dt;float flutter=Mathf.Sin(m.age*2+m.spin)*.006f;m.rect.anchoredPosition=Vector2.Scale(m.point+new Vector2(flutter,0),field.rect.size);m.rect.localRotation=Quaternion.Euler(0,0,m.age*m.spin);float fade=Mathf.Min(m.age*2,(m.life-m.age)*2);var c=m.colour;c.a*=Mathf.Clamp01(fade);m.image.color=c;}}
}
